<p>Прямая наименьших квадратов $\hat{y} = a + bx$ имеет угловой коэффициент $b = r\frac{s_y}{s_x}$ и проходит через $(\bar{x}; \bar{y})$, поэтому $a = \bar{y} - b\bar{x}$.</p>
